import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Stage 6 · Multi-device & Operations","description":"Hearth Stage 6 development module: event sync, device routing, offline queues, revocation and key rotation, backup and restore, long-running operations, and full audit.","frontmatter":{"title":"Stage 6 · Multi-device & Operations","description":"Hearth Stage 6 development module: event sync, device routing, offline queues, revocation and key rotation, backup and restore, long-running operations, and full audit.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-6.md","filePath":"en/delivery/stage-6.md","lastUpdated":1793761874000}'),o={name:"en/delivery/stage-6.md"};function r(l,e,s,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<p class="eyebrow">MODULE 6 / 7</p><h1 id="stage-6-·-multi-device-operations" tabindex="-1">Stage 6 · Multi-device &amp; Operations <a class="header-anchor" href="#stage-6-·-multi-device-operations" aria-label="Permalink to &quot;Stage 6 · Multi-device &amp; Operations&quot;">​</a></h1><p class="lead">Turn the local product into a long-running, multi-device, portable, and revocable personal Agent OS. Multi-device is not multiple agents: it is one logical identity, event history, memory, and authorization across devices.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Single-device install, recovery, backup, security, and upgrade paths work.</li><li>Events, leases, fencing tokens, memory versions, and device identity have stable contracts.</li><li>Multi-device operation cannot bypass approval, idempotency, or revocation boundaries.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Implement read and event sync.</strong> Add device identity, cursors, incremental sync, conflict handling, event replay, and projection consistency.</li><li><strong>Add capability routing and offline queues.</strong> Route GUI, file, and execution tasks by device capability; queue while offline, then replay idempotently without duplicate effects.</li><li><strong>Complete revocation and key rotation.</strong> Handle lost devices, remote revocation, key rotation, session invalidation, and secure migration.</li><li><strong>Complete backup, restore, and upgrade.</strong> Support encrypted backup, full restore, export/import, schema migration, executor version pinning, pre-upgrade checks, and rollback.</li><li><strong>Build long-running operations.</strong> Add health checks, quotas, logs, monitoring, resource reclamation, failure recovery, and long-term migration drills.</li><li><strong>Complete the system audit.</strong> Pass every stage exit, audit all eight task families, run red-team and fault injection, rehearse migration, and publish privacy, installer, upgrade, and final evaluation evidence.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><p>Each increment now has four layers: outcome and gate → four work packages → engineering map and interfaces → acceptance rehearsal. Packages can be split across developers, but merge in dependency order; completing one package does not complete the increment.</p><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-6/d6-1.html">D6.1</a> Multi-device read and event sync</td><td>Consistent tasks and artifacts across devices</td><td>Device identity, cursors, incremental sync, replay</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/d6-2.html">D6.2</a> Capability routing and offline queues</td><td>Tasks go to the right device and survive disconnection</td><td>Capability routing, offline queue, idempotent replay</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/d6-3.html">D6.3</a> Revocation, key rotation, and secure migration</td><td>Lost devices are revocable and data can move safely</td><td>Revocation, rotation, session invalidation, migration drill</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/d6-4.html">D6.4</a> Backup, restore, migration, and upgrade</td><td>Users can fully back up, restore, and upgrade</td><td>Encrypted backup, schema migration, rollback</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/d6-5.html">D6.5</a> Long-running operations and resources</td><td>The system runs long-term without daily maintenance</td><td>Health checks, quotas, monitoring, resource reclamation</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/d6-6.html">D6.6</a> Full audit and release</td><td>An installable, portable, revocable personal Agent OS</td><td>Eight-family coverage, red team, fault injection, final evaluation</td></tr></tbody></table><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] One logical agent stays consistent across devices; switching devices loses no tasks.</li><li>[ ] Offline recovery meets target; device switching and retries do not duplicate external effects.</li><li>[ ] Device revocation is immediate and blocks further approval or takeover.</li><li>[ ] Events, artifacts, memory, and skills verify after migration.</li><li>[ ] Long-running operation has no leaks, state drift, or unexplained permission expansion.</li><li>[ ] Install, upgrade, backup, restore, privacy, and export paths are complete.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Multiple inconsistent agents presented as multi-device support.</li><li>Using sync conflicts or offline queues to excuse duplicate effects.</li><li>Declaring completion without migration drills and revocation.</li></ul><h2 id="after-completion" tabindex="-1">After Completion <a class="header-anchor" href="#after-completion" aria-label="Permalink to &quot;After Completion&quot;">​</a></h2><p>After this module, the project enters long-term maintenance and expansion. More task families, connectors, and optimizations will follow, but foundational product, recovery, security, approval, and migration are no longer deferred work.</p>',16)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
